package com.ankit.joblens.profile;
import java.io.InputStream; import java.util.*;
import org.apache.tika.Tika; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import org.springframework.web.multipart.MultipartFile;
@Service public class ResumeProfileService {
 private final JdbcTemplate jdbc; private final Tika tika=new Tika(); public ResumeProfileService(JdbcTemplate jdbc){this.jdbc=jdbc;}
 public Map<String,Object> readAndApply(MultipartFile file) throws Exception { if(file.isEmpty()) throw new IllegalArgumentException("Resume file is empty"); String text; try(InputStream in=file.getInputStream()){text=tika.parseToString(in);} if(text.isBlank()) throw new IllegalArgumentException("Resume text could not be extracted"); String lower=text.toLowerCase(Locale.ROOT); List<String> skills=jdbc.query("select canonical_name from skill order by canonical_name",(rs,n)->rs.getString(1)).stream().filter(s->lower.contains(s.toLowerCase(Locale.ROOT))).toList(); Long profile=jdbc.queryForObject("select id from candidate_profile where name='default'",Long.class); jdbc.update("update candidate_profile set summary=? where id=?",text.lines().filter(l->!l.isBlank()).findFirst().orElse("Resume profile"),profile); jdbc.update("delete from candidate_skill where candidate_profile_id=?",profile); for(String skill:skills) jdbc.update("insert into candidate_skill(candidate_profile_id,skill_id,status,importance) select ?,id,'PRODUCTION',1.0 from skill where canonical_name=?",profile,skill); return Map.of("profileId",profile,"fileName",file.getOriginalFilename(),"extractedCharacters",text.length(),"detectedSkills",skills,"reviewRequired",true); }
}
